import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"OCI artifact paths and tags","description":"","frontmatter":{"id":"6497710059","title":"OCI artifact paths and tags","state":"Approved","created":"2026-10-15T00:00:00.000Z","tags":["oci","registry","docker","helm","wasm","sigstore","naming"],"category":"Platform"},"headers":[],"relativePath":"adrs/6497710059/README.md","filePath":"adrs/6497710059/README.md"}'),s={name:"adrs/6497710059/README.md"};function i(n,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="oci-artifact-paths-and-tags" tabindex="-1">OCI artifact paths and tags <a class="header-anchor" href="#oci-artifact-paths-and-tags" aria-label="Permalink to &quot;OCI artifact paths and tags&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../2078011537/README.html">ADR#2078011537</a> fixes where container images and Helm charts live in a repository. This ADR fixes where they, and the Wasm components and signatures we also publish, live in a registry and how they are tagged.</p><p>We publish to Amazon ECR, GitHub Container Registry and Google Artifact Registry, and each one takes a different part of the path before we get to name anything:</p><ul><li>ECR takes only the host, <code>&lt;account&gt;.dkr.ecr.&lt;region&gt;.amazonaws.com</code>, and needs a repository to exist before a push unless a create-on-push template matches its name prefix.</li><li>GitHub Container Registry takes the owner, <code>ghcr.io/&lt;owner&gt;</code>, and creates packages on push.</li><li>Artifact Registry takes the project and a repository resource, <code>&lt;location&gt;-docker.pkg.dev/&lt;project&gt;/&lt;repository&gt;</code>, and that repository must be created first.</li></ul><p>Two artifacts with the same name, such as the <code>api</code> image and the <code>api</code> chart, land in the same OCI repository unless something else in the path separates them. Their tags then collide, since both publish <code>1.2.0</code>. Helm also decides part of the path itself: <code>helm push</code> appends the chart name to the reference it is given, and uses the chart version as the tag.</p><p>Tags are the other source of drift. Charts and Wasm components only accept SemVer, while images had been tagged with SemVer, short SHAs, branch names and <code>latest</code>. ECR and Artifact Registry can both reject a push that moves an existing tag, and Artifact Registry cannot exempt <code>latest</code> from that rule.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><h3 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to &quot;Paths&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> publish every image and chart to <code>&lt;registry&gt;/&lt;kind&gt;/&lt;namespace&gt;/&lt;name&gt;</code>, where <code>&lt;registry&gt;</code> is the prefix the registry imposes (the ECR host, <code>ghcr.io/&lt;owner&gt;</code>, or <code>&lt;location&gt;-docker.pkg.dev/&lt;project&gt;</code>). Wasm components and mirrors take their own path, below.</p></li><li><p>You <strong>MUST</strong> use one of these kinds as the first segment after the prefix:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Artifact</th></tr></thead><tbody><tr><td><code>images</code></td><td>Container images</td></tr><tr><td><code>charts</code></td><td>Helm charts</td></tr><tr><td><code>wasm-components</code></td><td>Wasm components</td></tr><tr><td><code>mirrors</code></td><td>Third-party images we copy or cache</td></tr></tbody></table><p>In Artifact Registry each kind is a Docker-format repository of that name, except <code>mirrors</code>, which is a remote repository per upstream named <code>mirrors-&lt;upstream&gt;</code>. In ECR each kind is the prefix of a create-on-push or pull-through cache rule.</p></li><li><p>You <strong>MUST</strong> keep a mirrored image under <code>mirrors/&lt;upstream&gt;/&lt;path&gt;</code>, where <code>&lt;upstream&gt;</code> names the source registry (<code>docker-hub</code>, <code>quay</code>) and <code>&lt;path&gt;</code> and the tags are the upstream ones, unchanged, such as <code>mirrors/docker-hub/library/postgres:16</code>. It is not ours to rename, and keeping it out of <code>images/</code> keeps our builds apart from copies. In Artifact Registry the remote repository name takes the place of both segments, so the same image is <code>mirrors-docker-hub/library/postgres:16</code>.</p></li><li><p>A mirror is exempt from the <a href="#tags">Tags</a> rules. It has no build commit of ours, and its tags follow the upstream, so a refresh can move a mirrored tag when the upstream moves it (<a href="./references/aws.html#creating-repositories">ECR</a>). Deployments still pin it by digest.</p></li><li><p>You <strong>MUST</strong> set <code>&lt;namespace&gt;</code> to the logical group that builds and ships the image or chart together, usually named after the source repository that holds them, such as <code>atlas</code>. Every image and chart of that group shares it, and a registry rule, such as an ECR lifecycle policy or an IAM resource pattern, can target the group by prefix. You <strong>MUST NOT</strong> change it once published, so a renamed or split repository keeps publishing under the namespace it started with. It is not a Kubernetes namespace.</p></li><li><p>You <strong>MUST</strong> name an image or chart after the deployable it produces, the same <code>&lt;name&gt;</code> as its directory under <code>devops/docker/images/</code> or <code>devops/helm/charts/</code>. Push a chart to <code>oci://&lt;registry&gt;/charts/&lt;namespace&gt;</code> and let Helm append the name.</p></li><li><p>You <strong>MUST</strong> publish a Wasm component at <code>&lt;registry&gt;/wasm-components/&lt;namespace&gt;/&lt;package&gt;</code>, from its WIT package <code>&lt;namespace&gt;:&lt;package&gt;</code>. That namespace is the WIT one, global across the registry, and need not match the namespace of any image or chart. In <code>wkg</code>, set <code>oci.registry</code> to the registry host alone and put the rest of the prefix in <code>oci.namespacePrefix</code>: <code>wasm-components/</code> on ECR, <code>&lt;owner&gt;/wasm-components/</code> on GitHub Container Registry, and <code>&lt;project&gt;/wasm-components/</code> on Artifact Registry (<a href="./references/versions.html#wkg-and-the-wasm-component-path">wkg metadata</a>). On GitHub Container Registry that turns <code>acme:greeter</code> into <code>ghcr.io/&lt;owner&gt;/wasm-components/acme/greeter</code>.</p></li><li><p>You <strong>MUST</strong> keep every name unique within its kind and namespace, because nothing else in the path tells two deployables apart.</p></li><li><p>You <strong>MUST</strong> write every path segment we name in lowercase <code>[a-z0-9-]</code>, and <strong>MUST NOT</strong> use <code>.</code>, <code>_</code> or <code>__</code> even where the OCI grammar allows them. The upstream path of a mirror is not ours, so it stays as it is.</p></li><li><p>You <strong>MUST NOT</strong> put an environment or a team in the path. Every environment pulls the same artifact, and the exact source repository is linked through <code>org.opencontainers.image.source</code>, whatever the namespace.</p></li></ul><h3 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> tag a release with its full version, in one of these schemes, picked once per project and kept:</p><table tabindex="0"><thead><tr><th>Scheme</th><th>Form</th><th>Example</th></tr></thead><tbody><tr><td>SemVer</td><td><code>MAJOR.MINOR.PATCH</code></td><td><code>1.4.0</code></td></tr><tr><td>CalVer</td><td><code>YYYY.MDD.N</code></td><td><code>2026.1015.0</code></td></tr></tbody></table><p>In CalVer, <code>MDD</code> is the month followed by the day padded to two digits, so 5 April is <code>405</code>, and <code>N</code> counts the releases of that day from <code>0</code>.</p></li><li><p>You <strong>MUST NOT</strong> pad the month (<code>2026.0405.0</code>), add a <code>v</code> prefix, or add <code>+</code> build metadata. A leading zero, a prefix and build metadata all break SemVer, which charts and components require, and Helm rewrites <code>+</code> to <code>_</code>, which turns one version into two different tags. A git tag <strong>MAY</strong> keep the <code>v</code>, as in <code>v1.4.0</code>, and the build drops it from the artifact tag.</p></li><li><p>You <strong>MUST NOT</strong> count releases within a day with a prerelease such as <code>2026.1015.0-1</code>, because SemVer sorts a prerelease below its release.</p></li><li><p>You <strong>MUST</strong> tag every published artifact with the full commit SHA it was built from, marked by where the build came from, except a released chart or component. A digest identifies the bytes but cannot be looked up in git; the commit can.</p><table tabindex="0"><thead><tr><th>Build</th><th>Image tag</th><th>Chart or component tag</th></tr></thead><tbody><tr><td>Release</td><td>version + <code>&lt;commit&gt;</code></td><td>version</td></tr><tr><td>Default branch</td><td><code>&lt;commit&gt;</code></td><td><code>0.0.0-sha-&lt;commit&gt;</code></td></tr><tr><td>Pull request</td><td><code>pr-&lt;commit&gt;</code></td><td><code>0.0.0-pr-&lt;commit&gt;</code></td></tr></tbody></table><p>Charts and components only accept SemVer, so their builds that are not a release use a prerelease, which sorts below every release. Helm requires a chart&#39;s tag to equal its version, so a released chart or component carries only the version tag and its commit is read from <code>org.opencontainers.image.revision</code>. The <code>pr-</code> mark keeps a pull request build from taking the tag of the same commit built later on the default branch.</p><p>The version in the Release row belongs to the artifact in that column. A chart&#39;s version is not the version of its image, see the next rule.</p></li><li><p>You <strong>MUST</strong> version a chart on its own, by changes to the chart (its templates, values or schema), and <strong>MUST NOT</strong> derive its version from the release of the image it deploys. The chart&#39;s <code>appVersion</code>, and the image tag default in its values, name the image it deploys by default, and users <strong>MAY</strong> override the image to deploy another one. A new image release does not release the chart by itself. Moving the chart&#39;s default image is a chart change, so it releases a new chart version. Charts evolve on their own schedule, and lockstep versions would publish chart releases with no chart change and block a chart-only fix until the application releases.</p></li><li><p>The <code>0.0.0-sha-&lt;commit&gt;</code> chart of the default branch still points at the image of that same commit, and the <code>0.0.0-pr-&lt;commit&gt;</code> chart at the <code>pr-</code> image of its commit. They are builds of one commit, not releases, so the chart and image agree there and nowhere else.</p></li><li><p>You <strong>MUST</strong> release an image by adding the version tag to the artifact already built for that commit, never by building it again. A rebuild produces a new digest, which would either move the commit tag or leave two artifacts claiming the same commit.</p></li><li><p>You <strong>SHOULD</strong> expire pull request builds after an age the project sets, through the registry&#39;s cleanup policy matched on the <code>pr-</code> and <code>0.0.0-pr-</code> prefixes, or a scheduled job where the registry has none, as on GitHub Container Registry. Artifact Registry cannot delete a tagged artifact from a repository with immutable tags, so there immutability wins and pull request builds are kept (<a href="./references/gcp.html#tag-immutability">Artifact Registry</a>). You <strong>MUST NOT</strong> delete an artifact that carries a release tag.</p></li><li><p>You <strong>MUST NOT</strong> move a version or commit tag once it is published.</p></li><li><p>You <strong>MUST NOT</strong> publish a tag that moves, such as <code>latest</code>, <code>main</code>, a branch name or a partial version like <code>1.4</code>, for an artifact only we deploy.</p></li><li><p>You <strong>MAY</strong> add moving tags to an image that others pull, such as an open source release, since they expect a pull without a version to work. Only these are allowed:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Points at</th></tr></thead><tbody><tr><td><code>latest</code></td><td>The newest release</td></tr><tr><td><code>&lt;MAJOR&gt;.x</code></td><td>The newest release of that major, <code>1.x</code></td></tr><tr><td><code>canary</code></td><td>The newest build of the default branch</td></tr></tbody></table><p>You <strong>MUST NOT</strong> publish any other moving tag, such as <code>1</code>, <code>1.4</code> or a branch name. Charts and components <strong>MUST NOT</strong> get moving tags at all, because their clients resolve version ranges from the SemVer tags themselves.</p></li><li><p>You <strong>MUST</strong> publish every image as a multi-platform image index, and <strong>MUST NOT</strong> put an architecture or operating system in a tag or path. The client picks its platform from the index.</p></li><li><p>You <strong>MUST</strong> name an image variant, such as a debug or FIPS build, with a <code>-&lt;variant&gt;</code> suffix on any allowed tag, such as <code>1.4.0-debug</code> or <code>latest-debug</code>, and <strong>MUST NOT</strong> publish it under another name.</p></li><li><p>You <strong>MUST</strong> turn on tag immutability wherever the registry offers it. An image repository that carries moving tags <strong>MUST</strong> exempt exactly those tags and their variants, such as <code>latest-debug</code>, which rules out Artifact Registry, since it cannot exempt any. On ECR the exemptions are <code>latest*</code>, <code>canary*</code> and <code>*.x*</code> (<a href="./references/aws.html#tag-immutability">ECR</a>). GitHub Container Registry has no tag immutability, so there the tag rules hold only by convention.</p></li><li><p>You <strong>MUST</strong> reference an artifact from a deployment by tag and digest, <code>&lt;name&gt;:&lt;tag&gt;@sha256:&lt;digest&gt;</code>. The digest is what gets pulled; the tag tells a reader which release or commit it is.</p></li><li><p>You <strong>MUST</strong> set the <code>org.opencontainers.image.source</code> and <code>org.opencontainers.image.revision</code> annotations, so the artifact itself leads back to its repository and commit.</p></li></ul><h3 id="signatures-attestations-and-sboms" tabindex="-1">Signatures, attestations and SBOMs <a class="header-anchor" href="#signatures-attestations-and-sboms" aria-label="Permalink to &quot;Signatures, attestations and SBOMs&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> store signatures, attestations and SBOMs in the same repository as the artifact they describe, attached to its digest. You <strong>MUST NOT</strong> publish them under another path or kind.</p></li><li><p>You <strong>MUST</strong> copy them with the artifact whenever it moves to another registry, with a tool that follows referrers such as <code>oras copy -r</code>. A plain pull and push copies the artifact and leaves them behind, and <code>cosign copy</code> is deprecated (<a href="./references/versions.html#signatures">signatures</a>).</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ghcr.io/&lt;owner&gt;</span></span>
<span class="line"><span>├── images/shop/api                     1.4.0, &lt;commit&gt;, pr-&lt;commit&gt;</span></span>
<span class="line"><span>├── charts/shop/api                     2.1.0, 0.0.0-sha-&lt;commit&gt;</span></span>
<span class="line"><span>├── wasm-components/acme/greeter        0.3.0</span></span>
<span class="line"><span>└── mirrors/docker-hub/library/postgres 16</span></span></code></pre></div></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./references/walkthrough.html">Walkthrough: one service from pull request to production</a></li><li><a href="./references/aws.html">Amazon ECR research</a></li><li><a href="./references/gcp.html">Artifact Registry research</a></li><li><a href="./references/github.html">GitHub Container Registry research</a></li><li><a href="./references/versions.html">Versions and tooling research</a></li><li><a href="./../2078011537/README.html">ADR#2078011537</a>: Operational assets</li><li><a href="https://github.com/opencontainers/distribution-spec/blob/main/spec.md" target="_blank" rel="noreferrer">OCI Distribution Specification</a></li><li><a href="https://github.com/opencontainers/image-spec/blob/main/annotations.md" target="_blank" rel="noreferrer">OCI pre-defined annotation keys</a></li><li><a href="https://helm.sh/docs/topics/registries/" target="_blank" rel="noreferrer">Helm: Use OCI-based registries</a></li><li><a href="https://docs.aws.amazon.com/AmazonECR/latest/userguide/repository-creation-templates.html" target="_blank" rel="noreferrer">Amazon ECR repository creation templates</a></li><li><a href="https://docs.aws.amazon.com/AmazonECR/latest/userguide/image-tag-mutability.html" target="_blank" rel="noreferrer">Amazon ECR image tag mutability</a></li><li><a href="https://cloud.google.com/artifact-registry/docs/docker/names" target="_blank" rel="noreferrer">Artifact Registry repository and image names</a></li><li><a href="https://docs.github.com/en/packages/working-with-a-github-packages-registry/working-with-the-container-registry" target="_blank" rel="noreferrer">Working with the GitHub Container Registry</a></li><li><a href="https://github.com/bytecodealliance/wasm-pkg-tools/blob/main/docs/registry-metadata.md" target="_blank" rel="noreferrer">wasm-pkg-tools registry metadata</a></li><li><a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning 2.0.0</a></li><li><a href="https://calver.org/" target="_blank" rel="noreferrer">Calendar Versioning</a></li><li><a href="https://github.com/opencontainers/image-spec/blob/main/image-index.md" target="_blank" rel="noreferrer">OCI image index</a></li></ul>`,16)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
